// Asserts that a game instance matches expected win/loss state, remaining guesses, and revealed/hidden counts.
void helper_assert_game_state(const struct game_instance *game, int expected_won, int expected_lost, int expected_remaining, int expected_revealed, int expected_hidden) {
    assert(game != NULL);
    assert(is_game_won(game) == expected_won);
    assert(is_game_lost(game) == expected_lost);
    assert(get_remaining_guesses(game) == expected_remaining);
    assert(get_revealed_count(game) == expected_revealed);
    assert(get_hidden_count(game) == expected_hidden);
}

// Asserts that processing a guess returns the expected result and updates game state correctly.
void helper_assert_guess_result(struct game_instance *game, char guess, int expected_return, int expected_incorrect, const char *expected_hidden) {
    assert(game != NULL);
    int result = process_guess(game, guess);
    assert(result == expected_return);
    assert(game->incorrect == expected_incorrect);
    assert(strcmp(game->hidden, expected_hidden) == 0);
}

