// ========== Searched From Pool - Utility Operations ==========

// Function: capture_stdout_start (from helper pool)
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(cap->pipe_write_fd);
    /* Restore original stdout */
    dup2(cap->saved_stdout_fd, STDOUT_FILENO);
    close(cap->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(cap->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(cap->pipe_read_fd);
                free(cap);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buffer;
}

// ========== Created - Utility Operations ==========

// Creates and returns a dynamically allocated game instance initialized with a given word.
struct game_instance *helper_create_game_instance(const char *word) {
    if (word == NULL) return NULL;
    struct game_instance *game = malloc(sizeof(struct game_instance));
    if (game == NULL) return NULL;
    init_game_instance(game, word);
    return game;
}

// Creates and returns a dynamically allocated game instance with a random word from a given array.
struct game_instance *helper_create_game_from_words(const char **words, int num_words) {
    if (words == NULL || num_words <= 0) return NULL;
    srand(time(NULL));
    struct game_instance game = new_game_from_words(words, num_words);
    struct game_instance *game_ptr = malloc(sizeof(struct game_instance));
    if (game_ptr == NULL) return NULL;
    *game_ptr = game;
    return game_ptr;
}

// Resets a game instance to initial state with a new word, clearing guesses and incorrect count.
void helper_reset_game_instance(struct game_instance *game, const char *word) {
    if (game == NULL || word == NULL) return;
    init_game_instance(game, word);
}


